2️⃣ Bundlers
What &amp; Why
Transform, optimize, and bundle modules for browser/Node. Handle:

Module resolution (ESM, CommonJS, JSON, CSS, assets)
Tree shaking (dead code elimination)
Code splitting (lazy loading)
Minification (terser)
Dev server (HMR, proxy)


Webpack — Mature, Configurable
npm install -D webpack webpack-cli webpack-dev-server
webpack.config.js
const path = require(&quot;path&quot;);
const HtmlWebpackPlugin = require(&quot;html-webpack-plugin&quot;);
const MiniCssExtractPlugin = require(&quot;mini-css-extract-plugin&quot;);
const { DefinePlugin } = require(&quot;webpack&quot;);

module.exports = (env, argv) =&gt; {
  const isProd = argv.mode === &quot;production&quot;;

  return {
    // Entry points
    entry: {
      main: &quot;./src/index.js&quot;,
      vendor: [&quot;lodash&quot;, &quot;axios&quot;] // Separate vendor chunk
    },

    // Output
    output: {
      path: path.resolve(__dirname, &quot;dist&quot;),
      filename: isProd ? &quot;[name].[contenthash].js&quot; : &quot;[name].js&quot;,
      chunkFilename: isProd ? &quot;[name].[contenthash].chunk.js&quot; : &quot;[name].chunk.js&quot;,
      clean: true,                    // Clean dist before build
      publicPath: &quot;/&quot;,                // CDN path
      assetModuleFilename: &quot;assets/[hash][ext][query]&quot;
    },

    // Mode
    mode: isProd ? &quot;production&quot; : &quot;development&quot;,

    // Devtool (source maps)
    devtool: isProd ? &quot;source-map&quot; : &quot;eval-cheap-module-source-map&quot;,

    // Dev server
    devServer: {
      static: &quot;./dist&quot;,
      hot: true,                      // HMR
      port: 3000,
      open: true,
      historyApiFallback: true,       // SPA routing
      proxy: {
        &quot;/api&quot;: &quot;http://localhost:4000&quot;
      }
    },

    // Module resolution
    resolve: {
      extensions: [&quot;.js&quot;, &quot;.jsx&quot;, &quot;.ts&quot;, &quot;.tsx&quot;, &quot;.json&quot;],
      alias: {
        &quot;@&quot;: path.resolve(__dirname, &quot;src&quot;),
        &quot;@components&quot;: path.resolve(__dirname, &quot;src/components&quot;)
      },
      modules: [&quot;node_modules&quot;, &quot;src&quot;]
    },

    // Module rules (loaders)
    module: {
      rules: [
        // JavaScript/TypeScript
        {
          test: /\.[jt]sx?$/,
          exclude: /node_modules/,
          use: {
            loader: &quot;babel-loader&quot;,
            options: {
              presets: [
                [&quot;@babel/preset-env&quot;, { targets: &quot;defaults&quot; }],
                &quot;@babel/preset-react&quot;,
                &quot;@babel/preset-typescript&quot;
              ]
            }
          }
        },
        // CSS
        {
          test: /\.css$/,
          use: [
            isProd ? MiniCssExtractPlugin.loader : &quot;style-loader&quot;,
            &quot;css-loader&quot;,
            &quot;postcss-loader&quot;
          ]
        },
        // Sass
        {
          test: /\.s[ac]ss$/,
          use: [
            isProd ? MiniCssExtractPlugin.loader : &quot;style-loader&quot;,
            &quot;css-loader&quot;,
            &quot;postcss-loader&quot;,
            &quot;sass-loader&quot;
          ]
        },
        // Images/Fonts/Assets
        {
          test: /\.(png|jpe?g|gif|svg|woff2?|ttf|eot)$/,
          type: &quot;asset/resource&quot;
        },
        // Inline small images
        {
          test: /\.(png|jpe?g|gif|svg)$/,
          type: &quot;asset&quot;,
          parser: { dataUrlCondition: { maxSize: 8 * 1024 } }
        }
      ]
    },

    // Plugins
    plugins: [
      new HtmlWebpackPlugin({
        template: &quot;./public/index.html&quot;,
        minify: isProd
      }),
      new MiniCssExtractPlugin({
        filename: isProd ? &quot;[name].[contenthash].css&quot; : &quot;[name].css&quot;
      }),
      new DefinePlugin({
        &quot;process.env.NODE_ENV&quot;: JSON.stringify(process.env.NODE_ENV),
        &quot;process.env.API_URL&quot;: JSON.stringify(process.env.API_URL)
      })
    ],

    // Optimization
    optimization: {
      splitChunks: {
        chunks: &quot;all&quot;,
        cacheGroups: {
          vendor: {
            test: /[\\/]node_modules[\\/]/,
            name: &quot;vendors&quot;,
            priority: 10
          },
          common: {
            minChunks: 2,
            priority: 5,
            reuseExistingChunk: true
          }
        }
      },
      runtimeChunk: &quot;single&quot;,
      minimize: isProd,
      minimizer: [
        new TerserPlugin({
          terserOptions: {
            compress: { drop_console: isProd }
          }
        })
      ]
    },

    // Performance hints
    performance: {
      maxAssetSize: 250000,
      maxEntrypointSize: 250000
    }
  };
};
Key Webpack Concepts





































ConceptDescriptionEntryStarting point(s) for dependency graphOutputWhere/how to emit bundlesLoadersTransform non-JS files (babel, css, file)PluginsHook into build lifecycle (HtmlWebpackPlugin, DefinePlugin)ChunksOutput files (entry, async, vendor)Tree ShakingRemove unused exports (needs ESM + sideEffects: false)Code Splittingimport() dynamic imports → separate chunks

Vite — Fast, Modern, Unbundled Dev
npm create vite@latest my-app -- --template react-ts
cd my-app
npm install
npm run dev
vite.config.js
import { defineConfig } from &quot;vite&quot;;
import react from &quot;@vitejs/plugin-react&quot;;
import path from &quot;path&quot;;

export default defineConfig(({ mode }) =&gt; {
  const isProd = mode === &quot;production&quot;;

  return {
    plugins: [react()],

    resolve: {
      alias: {
        &quot;@&quot;: path.resolve(__dirname, &quot;./src&quot;),
      }
    },

    // Dev server
    server: {
      port: 3000,
      open: true,
      proxy: {
        &quot;/api&quot;: {
          target: &quot;http://localhost:4000&quot;,
          changeOrigin: true
        }
      }
    },

    // Build (uses Rollup under the hood)
    build: {
      outDir: &quot;dist&quot;,
      sourcemap: true,
      minify: &quot;terser&quot;,
      terserOptions: {
        compress: { drop_console: isProd }
      },
      rollupOptions: {
        output: {
          manualChunks: {
            vendor: [&quot;react&quot;, &quot;react-dom&quot;, &quot;react-router-dom&quot;],
            utils: [&quot;lodash&quot;, &quot;date-fns&quot;]
          }
        }
      },
      chunkSizeWarningLimit: 500
    },

    // CSS
    css: {
      modules: {
        localsConvention: &quot;camelCase&quot;
      },
      preprocessorOptions: {
        scss: {
          additionalData: `@use &quot;@/styles/variables&quot; as *;`
        }
      }
    },

    // Environment variables
    envPrefix: &quot;VITE_&quot;,  // Only VITE_* exposed to client
    define: {
      __APP_VERSION__: JSON.stringify(process.env.npm_package_version)
    }
  };
});
Vite vs Webpack













































