// math.test.ts
import { add, multiply } from &quot;./math&quot;;

describe(&quot;Math utilities&quot;, () =&gt; {
  describe(&quot;add&quot;, () =&gt; {
    test(&quot;adds two positive numbers&quot;, () =&gt; {
